import { usePasswordVisibility } from './usePasswordVisibility';
import './styles.css';

export type Props = {
  initialValue: string;
  onChange: (value: string) => void;
};

export function Component({ initialValue, onChange }: Props) {
  const { value, visible, updateValue, toggleVisibility } =
    usePasswordVisibility(initialValue, onChange);

  return (
    <div data-testid="panel" className="password-panel">
      <label>
        Password
        <input
          type={visible ? 'text' : 'password'}
          value={value}
          onChange={(event) => updateValue(event.currentTarget.value)}
        />
      </label>
      <button
          type="button"
          aria-pressed={visible}
          onClick={toggleVisibility}
      >
        Toggle visibility
      </button>
    </div>
  );
}

